<?php
declare(strict_types=1);
define('XAR_SPECIAL_FIXTURE_ONLY',true);require __DIR__.'/tactical-special-effects.php';
$presets=applicationConfiguredPassiveAbilities(['id'=>'character-amxWfdDZFvFZjLzT']);
function passiveNativeCommand(MemoryConnection $db,string $command,array $args,bool $gm=true):TestResponse{return runCommand($db,$command,['requestId'=>'passive-'.randomToken(18),'sceneId'=>'scene-one','characterId'=>'character-player','tokenId'=>'token-player',...$args],$gm,$gm?'account-gm':'account-player');}
function passiveNativeSource(MemoryConnection $db,array $passives):void{$c=$db->payload('character:character-player');$c['passiveAbilities']=$passives;$db->put('character:character-player',$c);$db->put('token:scene-one:token-player',synchronizeOnlineCharacterToken($db->payload('token:scene-one:token-player'),$c));}
$db=specialFixture();passiveNativeSource($db,$presets);
$template=['id'=>'native-resistance-test','name'=>'Préparation fictive','kind'=>'potion','active'=>['version'=>1,'effects'=>[['kind'=>'damage','components'=>[['type'=>'ignore','formula'=>'40']]],['kind'=>'dot','label'=>'Poison de recette','family'=>'poison','formula'=>'40','damageType'=>'ignore','turns'=>3]]]];
specialCheck(passiveNativeCommand($db,'item.template.create',['template'=>$template])->status===200,'Native potion template');
