$request='passive-once-'.randomToken(18);$args=['requestId'=>$request,'itemId'=>'native-bottle','expectedItemRevision'=>1];$result=passiveNativeCommand($db,'item.consume',$args,false);
specialCheck($result->status===200,'Real potion consumption: '.json_encode($result->body));specialCheck($db->payload('character:character-player')['resources']['hp']===70,'Forty ignore-armour potion damage becomes thirty');
$dot=$db->payload('activity')['damageOverTime'][0];specialCheck($dot['remainingTurns']===2&&$dot['sourceItemKind']==='potion','Poison/potion overlap subtracts only one turn');
specialCheck(!empty(passiveNativeCommand($db,'item.consume',$args,false)->body['deduplicated']),'Native receipt does not consume twice');specialCheck($db->payload('character:character-player')['resources']['hp']===70,'Native receipt leaves HP untouched');
$records=applicationDomainRecords($db,['activity','token:scene-one:token-player','character:character-player']);$pending=[];$health=applyOnlineAttackDamage($db,$records,$pending,'token:scene-one:token-player',$db->payload('token:scene-one:token-player'),40,false,['rawDamage'=>40,'finalDamage'=>40,'armorPercent'=>0,'damageType'=>'ignore','family'=>'poison']);
specialCheck($health['appliedDamage']===30&&$health['passivePreventedDamage']===10,'Periodic poison uses the same authoritative passive reduction');specialCheck($pending['character:character-player']['payload']['resources']['hp']===40,'Periodic reduction queues the correct durable HP');
$db=specialFixture();passiveNativeSource($db,$presets);$c=$db->payload('character:character-player');$c['abilities']=[['id'=>'native-infusion','name'=>'Infusion de recette','effect'=>'damage','formula'=>'10','damageType'=>'ignore','castingStatId'=>'','manaCost'=>0,'fatigueCost'=>0,'cooldownRounds'=>0,'restRecharge'=>'none','reusableInTurn'=>true,'infusion'=>['version'=>1,'enabled'=>true,'ratio'=>1,'minimumMana'=>0,'refundOnMiss'=>true]]];$db->put('character:character-player',$c);
$result=passiveNativeCommand($db,'token.attack',['sourceTokenId'=>'token-player','targetTokenId'=>'token-monster','attackKind'=>'ability','attackId'=>'native-infusion','infusionMana'=>3,'opposed'=>false]);specialCheck($result->status===200,'Native infused attack: '.json_encode($result->body));
specialCheck($db->payload('token:scene-one:token-monster')['hp']===484,'Native infusion adds six damage to ten base damage');specialCheck($db->payload('character:character-player')['resources']['mana']===97,'Native infusion still spends three mana');specialCheck($db->payload('character:character-player')['fatigue']['current']===1,'Hyperactive remains charged only once');
$db=specialFixture();$c=$db->payload('character:character-player');$c['stats']['force']=55;$c['abilities']=[['id'=>'native-distance','name'=>'Tir de recette','effect'=>'damage','formula'=>'10','damageType'=>'ignore','castingStatId'=>'character-stat-force','projectile'=>true,'rangeCells'=>15,'manaCost'=>0,'fatigueCost'=>0,'cooldownRounds'=>0,'restRecharge'=>'none','reusableInTurn'=>true]];$db->put('character:character-player',$c);$target=$db->payload('token:scene-one:token-monster');$target['passiveAbilities']=array_values(array_filter($presets,static fn($p)=>$p['kind']==='ranged-target-evasion'));$db->put('token:scene-one:token-monster',$target);
$result=passiveNativeCommand($db,'token.attack',['sourceTokenId'=>'token-player','targetTokenId'=>'token-monster','attackKind'=>'ability','attackId'=>'native-distance','statId'=>'character-stat-force','opposed'=>false]);specialCheck($result->status===200,'Native ranged attack: '.json_encode($result->body));$receipt=$db->payload('activity')['attackReceipts'][0]['attack'];specialCheck($receipt['hit']['outcome']['modifier']===-10,'Native target passive lowers attacker threshold by ten');specialCheck($db->payload('character:character-player')['stats']['force']===55,'No edit to attacker base statistic');
echo json_encode(['ok'=>true,'checks'=>$specialChecks,'productionAccess'=>false],JSON_THROW_ON_ERROR)."\n";
